uint32_t* neighborTable = new uint32_t[particleCount];
std::unordered_map<uint32_t, uint32_t> cellMap;
uint32_t currentIndex = 0;
for (size_t i = 0; i < particleCount; ++i) {
    uint32_t cellHash = sortedParticles[i].getCellHash();
    if (cellMap.find(cellHash) == cellMap.end()) {
        cellMap[cellHash] = currentIndex;
        neighborTable[currentIndex++] = cellHash;
    }
}
neighborTable = std::realloc(neighborTable, currentIndex * sizeof(uint32_t));
return neighborTable;

